#include "Engine/StaticMesh.h"
#include "EngineUtils.h"
#include "Editor.h"
#include "PhysicsEngine/BodySetup.h"
#include "Misc/FileHelper.h"
#include "Misc/Paths.h"
#include "Serialization/JsonWriter.h"
#include "Serialization/JsonSerializer.h"

namespace MCPModelInspection
{
 struct FStaticMeshInspectionSummary { FString AssetPath; TArray<FString> MaterialPaths; int32 LODCount=0; int32 MaterialSlotCount=0; int32 VertexCount=0; int32 TriangleCount=0; FVector BoundsOrigin=FVector::ZeroVector; FVector BoundsExtent=FVector::ZeroVector; bool HasBodySetup=false; FString CollisionStatus=TEXT("body_setup_present"); FString NaniteStatus=TEXT("not_exposed"); };
 FStaticMeshInspectionSummary Inspect(const UStaticMesh* Mesh) { FStaticMeshInspectionSummary Out; if(!Mesh) return Out; Out.AssetPath=Mesh->GetPathName(); Out.MaterialSlotCount=Mesh->GetStaticMaterials().Num(); for(const FStaticMaterial& M : Mesh->GetStaticMaterials()) Out.MaterialPaths.Add(M.MaterialInterface ? M.MaterialInterface->GetPathName() : FString()); Out.HasBodySetup=Mesh->GetBodySetup()!=nullptr; const FBoxSphereBounds B=Mesh->GetBounds(); Out.BoundsOrigin=B.Origin; Out.BoundsExtent=B.BoxExtent; const FStaticMeshRenderData* RD=Mesh->GetRenderData(); if(RD){Out.LODCount=RD->LODResources.Num(); if(Out.LODCount>0){const FStaticMeshLODResources& L=RD->LODResources[0]; Out.VertexCount=L.GetNumVertices(); Out.TriangleCount=L.GetNumTriangles();}} return Out; }
 void RunInspection(const TArray<FString>& Args) { const FString AssetPath=Args.Num()>0?Args[0]:TEXT("/Engine/BasicShapes/Cube.Cube"); const FString OutputPath=Args.Num()>1?Args[1]:FPaths::Combine(FPaths::ProjectSavedDir(),TEXT("MCPNativeInspection.json")); const UStaticMesh* Mesh=LoadObject<UStaticMesh>(nullptr,*AssetPath); const auto S=Inspect(Mesh); TSharedRef<FJsonObject> O=MakeShared<FJsonObject>(); O->SetBoolField(TEXT("ok"),Mesh!=nullptr); O->SetStringField(TEXT("assetPath"),S.AssetPath); O->SetNumberField(TEXT("lodCount"),S.LODCount); O->SetNumberField(TEXT("materialSlotCount"),S.MaterialSlotCount); TArray<TSharedPtr<FJsonValue>> Mats; for(const FString& P : S.MaterialPaths) Mats.Add(MakeShared<FJsonValueString>(P)); O->SetArrayField(TEXT("materialPaths"),Mats); O->SetStringField(TEXT("collisionStatus"),S.CollisionStatus); O->SetStringField(TEXT("naniteStatus"),S.NaniteStatus); O->SetNumberField(TEXT("vertexCount"),S.VertexCount); O->SetNumberField(TEXT("triangleCount"),S.TriangleCount); O->SetBoolField(TEXT("hasBodySetup"),S.HasBodySetup); TSharedRef<FJsonObject> B=MakeShared<FJsonObject>(); B->SetNumberField(TEXT("x"),S.BoundsExtent.X); B->SetNumberField(TEXT("y"),S.BoundsExtent.Y); B->SetNumberField(TEXT("z"),S.BoundsExtent.Z); O->SetObjectField(TEXT("boundsExtent"),B); FString Text; auto W=TJsonWriterFactory<>::Create(&Text); FJsonSerializer::Serialize(O,W); FFileHelper::SaveStringToFile(Text,*OutputPath); }
}
namespace MCPModelInspection { void RunActorInspection(const TArray<FString>& Args) { const FString ActorLabel=Args.Num()>0?Args[0]:TEXT(""); const FString OutputPath=Args.Num()>1?Args[1]:FPaths::Combine(FPaths::ProjectSavedDir(),TEXT("MCPNativeActorInspection.json")); UWorld* World=GEditor?GEditor->GetEditorWorldContext().World():nullptr; AActor* Found=nullptr; if(World) for(TActorIterator<AActor> It(World);It;++It) if(It->GetActorLabel()==ActorLabel || It->GetPathName()==ActorLabel){Found=*It;break;} TSharedRef<FJsonObject> O=MakeShared<FJsonObject>(); O->SetBoolField(TEXT("ok"),Found!=nullptr); O->SetStringField(TEXT("label"),Found?Found->GetActorLabel():ActorLabel); O->SetStringField(TEXT("path"),Found?Found->GetPathName():TEXT("")); O->SetStringField(TEXT("class"),Found?Found->GetClass()->GetName():TEXT("")); if(Found){FVector L=Found->GetActorLocation(); FVector S=Found->GetActorScale3D(); O->SetStringField(TEXT("location"),L.ToString()); O->SetStringField(TEXT("scale"),S.ToString()); FBox Bounds; Found->GetActorBounds(false, L, S); O->SetStringField(TEXT("boundsOrigin"),L.ToString()); O->SetStringField(TEXT("boundsExtent"),S.ToString()); TArray<UActorComponent*> Components; Found->GetComponents(Components); O->SetNumberField(TEXT("componentCount"),Components.Num());} FString Text; auto W=TJsonWriterFactory<>::Create(&Text); FJsonSerializer::Serialize(O,W); FFileHelper::SaveStringToFile(Text,*OutputPath); } }